-- Seed data for AI-Budgeting (generated by docs/seed/build_backend_seed.py)
-- Source: AI Shopping for Budgeting — seed product dataset v2.0.0, 55 products / 283 listings
-- Prices are indicative South African retail, Durban, September 2026.
-- Safe to re-run: every statement is keyed on an external id.
--
-- If you ran an EARLIER version of this file more than once, your stores
-- table is duplicated (that version's ON CONFLICT DO NOTHING had no unique
-- key to fire on). Check with:
--   SELECT count(*), count(DISTINCT external_store_id) FROM stores;
-- If those two numbers differ, drop and recreate the database, then run
-- schema.sql and this file once each.

BEGIN;

-- One source row so the offers have a provenance, as the schema intends.
INSERT INTO retailer_sources (name, source_type, base_url, is_active)
SELECT 'Manual seed — Durban, Sept 2026', 'mixed', NULL, TRUE
WHERE NOT EXISTS (
  SELECT 1 FROM retailer_sources WHERE name = 'Manual seed — Durban, Sept 2026'
);

