  ('Wired Earphones', 'Sony', '3.5mm', 'Audio'),
  ('Power Bank', 'Romoss', '10000mAh', 'Power'),
  ('Multi-Plug Adaptor', 'Ellies', '4-way', 'Power'),
  ('LED Desk Lamp', 'Eurolux', 'Small', 'Lighting'),
  ('Single Fitted Sheet', 'Sheraton', 'Single', 'Bedding'),
  ('Bath Towel', 'Colibri', 'Large', 'Bathroom'),
  ('2-Plate Hotplate', 'Salton', 'Compact', 'Kitchen'),
  ('Kettle', 'Russell Hobbs', '1.7L', 'Kitchen'),
  ('Storage Crate', 'Addis', '30L', 'Storage'),
  ('LED Light Bulb', 'Eurolux', '9W E27', 'Lighting'),
  ('AA Batteries', 'Duracell', '4 pack', 'Batteries'),
  ('Duct Tape', 'Tesa', '48mm x 10m', 'Repairs'),
  ('Super Glue', 'Pratley', '3g', 'Repairs'),
  ('Padlock', 'Yale', '40mm', 'Security'),
  ('Extension Cord', 'Ellies', '5m', 'Electrical')
) AS v(name, brand, size, subcategory)
WHERE p.name = v.name
  AND COALESCE(p.brand,'') = COALESCE(v.brand,'')
  AND COALESCE(p.size,'')  = COALESCE(v.size,'')
  AND p.subcategory IS DISTINCT FROM v.subcategory;

-- product_offers: 283 listings — the same item at several stores,
-- which is what makes the comparison screen worth anything.
-- total_cost is a GENERATED column, so it is never inserted here.
INSERT INTO product_offers
  (product_id, store_id, external_product_id, price, shipping_cost, currency,
   availability_status, rating)
SELECT p.id, s.id, 'P001', 40.49, 0.00, 'ZAR', 'available', 4.4
FROM products p, stores s
WHERE p.name = 'Super Maize Meal'
  AND COALESCE(p.brand,'') = COALESCE('Ace','')
  AND COALESCE(p.size,'')  = COALESCE('2.5kg','')
  AND s.external_store_id  = 'shoprite'
ON CONFLICT (store_id, external_product_id) DO UPDATE
  SET price = EXCLUDED.price,
      shipping_cost = EXCLUDED.shipping_cost,
      availability_status = EXCLUDED.availability_status,
      rating = EXCLUDED.rating,
      last_checked_at = NOW();
